const ajustes = $('Obtener Ajustes de Inventario').all();
const movimientos = $('Obtener Movimientos de Stock').all();

let tablaHTML = `
<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px;">
  <thead style="background-color:#2c7be5;color:white;">
    <tr>
      <th>Ajuste</th>
      <th>Fecha</th>
      <th>Responsable</th>
      <th>Producto</th>
      <th>Cantidad Esperada</th>
      <th>Cantidad Real</th>
      <th>Diferencia</th>
      <th>Ubicación</th>
    </tr>
  </thead>
  <tbody>
`;

for (const ajuste of ajustes) {
  const aj = ajuste.json;
  const movs = movimientos.filter(m => m.json.inventory_id && m.json.inventory_id[0] === aj.id);

  if (movs.length === 0) {
    tablaHTML += `
    <tr>
      <td>${aj.name || 'Sin nombre'}</td>
      <td>${aj.date || ''}</td>
      <td>${aj.user_id ? aj.user_id[1] : 'N/A'}</td>
      <td colspan="4" style="text-align:center;color:#888;">Sin movimientos registrados</td>
      <td></td>
    </tr>`;
  } else {
    for (let i = 0; i < movs.length; i++) {
      const m = movs[i].json;
      const esperado = m.product_uom_qty || 0;
      const real = m.quantity_done || 0;
      const diferencia = real - esperado;
      const colorDif = diferencia < 0 ? 'color:red;' : diferencia > 0 ? 'color:green;' : 'color:gray;';

      tablaHTML += `
      <tr style="background-color:${i % 2 === 0 ? '#f9f9f9' : '#ffffff'}">
        ${i === 0 ? `<td rowspan="${movs.length}">${aj.name || 'Sin nombre'}</td>` : ''}
        ${i === 0 ? `<td rowspan="${movs.length}">${new Date(aj.date).toLocaleString('es-MX')}</td>` : ''}
        ${i === 0 ? `<td rowspan="${movs.length}">${aj.user_id ? aj.user_id[1] : 'N/A'}</td>` : ''}
        <td>${m.product_id ? m.product_id[1] : 'N/A'}</td>
        <td style="text-align:center;">${esperado}</td>
        <td style="text-align:center;">${real}</td>
        <td style="text-align:center;${colorDif}"><b>${diferencia > 0 ? '+' : ''}${diferencia}</b></td>
        <td>${m.location_id ? m.location_id[1] : ''} → ${m.location_dest_id ? m.location_dest_id[1] : ''}</td>
      </tr>`;
    }
  }
}

tablaHTML += `
  </tbody>
</table>`;

const totalAjustes = ajustes.length;
const totalMovimientos = movimientos.length;

return [{
  json: {
    tablaHTML,
    totalAjustes,
    totalMovimientos,
    fecha: new Date().toLocaleString('es-MX')
  }
}];
